#[no_mangle]
pub unsafe extern "C" fn neural_network_perceptron_classifier(v:*const i64,n:usize,out:*mut u8,cap:usize)->i64{if v.is_null()||n<5{return -1}let a=std::slice::from_raw_parts(v,n);let f=a[0];let s=a[1];let bias=a[2];if !(1..=3).contains(&f)||!(1..=4).contains(&s)||!(-10000..=10000).contains(&bias)||n!=3+f as usize+f as usize*s as usize{return -1}if a[3..3+f as usize].iter().any(|x|!(-10000..=10000).contains(x))||a[3+f as usize..].iter().any(|x|!(-10..=10).contains(x)){return -1}if out.is_null()||cap<s as usize{return -2}for j in 0..s as usize{let mut z=bias;for i in 0..f as usize{z+=a[3+i]*a[3+f as usize+i*s as usize+j]}*out.add(j)=u8::from(z>0)}s}
